 520: 
 521: impl TypedMinMax {
 522:     fn add(&mut self, typ: FieldType, sample: &[u8]) {
 523:         self.str_len.add(sample.len());
 524:         if sample.is_empty() {
 525:             return;
 526:         }
 527:         self.strings.add(sample.to_vec());
 528:         match typ {
 529:             TUnicode | TUnknown | TNull => {}
 530:             TFloat => {
 531:                 let n = str::from_utf8(&*sample)
 532:                             .ok()
 533:                             .and_then(|s| s.parse::<f64>().ok())
 534:                             .unwrap();
 535:                 self.floats.add(n);
 536:                 self.integers.add(n as i64);
 537:             }
 538:             TInteger => {
 539:                 let n = str::from_utf8(&*sample)
 540:                             .ok()
 541:                             .and_then(|s| s.parse::<i64>().ok())
 542:                             .unwrap();
 543:                 self.integers.add(n);
 544:                 self.floats.add(n as f64);
 545:             }
 546:         }
 547:     }
 548: 
 549:     fn len_range(&self) -> Option<(String, String)> {
 550:         match (self.str_len.min(), self.str_len.max()) {
 551:             (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
 552:             _ => None,
 553:         }
 554:     }
 555: 
 556:     fn show(&self, typ: FieldType) -> Option<(String, String)> {
 557:         match typ {
 558:             TNull => None,
 559:             TUnicode | TUnknown => {
 560:                 match (self.strings.min(), self.strings.max()) {
 561:                     (Some(min), Some(max)) => {
 562:                         let min = String::from_utf8_lossy(&**min).to_string();
 563:                         let max = String::from_utf8_lossy(&**max).to_string();
 564:                         Some((min, max))
 565:                     }
 566:                     _ => None
 567:                 }
 568:             }
 569:             TInteger => {
 570:                 match (self.integers.min(), self.integers.max()) {
 571:                     (Some(min), Some(max)) => {
 572:                         Some((min.to_string(), max.to_string()))
