 114: 
 115:     fn counts(&self, ftab: &FTable) -> Vec<(ByteString, u64)> {
 116:         let mut counts = if self.flag_asc {
 117:             ftab.least_frequent()
 118:         } else {
 119:             ftab.most_frequent()
 120:         };
 121:         if self.flag_limit > 0 {
 122:             counts = counts.into_iter().take(self.flag_limit).collect();
 123:         }
 124:         counts.into_iter().map(|(bs, c)| {
 125:             if b"" == &**bs {
 126:                 (b"(NULL)"[..].to_vec(), c)
 127:             } else {
 128:                 (bs.clone(), c)
 129:             }
 130:         }).collect()
 131:     }
 132: 
 133:     fn sequential_ftables(&self) -> CliResult<(Headers, FTables)> {
 134:         let mut rdr = self.rconfig().reader()?;
 135:         let (headers, sel) = self.sel_headers(&mut rdr)?;
 136:         Ok((headers, self.ftables(&sel, rdr.byte_records())?))
 137:     }
 138: 
 139:     fn parallel_ftables(&self, idx: &mut Indexed<fs::File, fs::File>)
 140:                        -> CliResult<(Headers, FTables)> {
 141:         let mut rdr = self.rconfig().reader()?;
 142:         let (headers, sel) = self.sel_headers(&mut rdr)?;
 143: 
 144:         if idx.count() == 0 {
 145:             return Ok((headers, vec![]));
 146:         }
 147: 
 148:         let chunk_size = util::chunk_size(idx.count() as usize, self.njobs());
 149:         let nchunks = util::num_of_chunks(idx.count() as usize, chunk_size);
 150: 
 151:         let pool = ThreadPool::new(self.njobs());
 152:         let (send, recv) = chan::sync(0);
 153:         for i in 0..nchunks {
 154:             let (send, args, sel) = (send.clone(), self.clone(), sel.clone());
 155:             pool.execute(move || {
 156:                 let mut idx = args.rconfig().indexed().unwrap().unwrap();
 157:                 idx.seek((i * chunk_size) as u64).unwrap();
 158:                 let it = idx.byte_records().take(chunk_size);
 159:                 send.send(args.ftables(&sel, it).unwrap());
 160:             });
 161:         }
 162:         drop(send);
 163:         Ok((headers, merge_all(recv.iter()).unwrap()))
 164:     }
