 188:     fn sel_headers<R: io::Read>(&self, rdr: &mut csv::Reader<R>)
 189:                   -> CliResult<(csv::ByteRecord, Selection)> {
 190:         let headers = rdr.byte_headers()?;
 191:         let sel = self.rconfig().selection(headers)?;
 192:         Ok((sel.select(headers).map(|h| h.to_vec()).collect(), sel))
 193:     }
 194: 
 195:     fn njobs(&self) -> usize {
 196:         if self.flag_jobs == 0 { util::num_cpus() } else { self.flag_jobs }
 197:     }
