 299:                                         with --no-headers set.", s));
 300:                 }
 301:                 let mut num_found = 0;
 302:                 for (i, field) in first_record.iter().enumerate() {
 303:                     if field == s.as_bytes() {
 304:                         if num_found == sidx {
 305:                             return Ok(i);
