 454: /// TypedSum keeps a rolling sum of the data seen.
 455: ///
 456: /// It sums integers until it sees a float, at which point it sums floats.
 457: #[derive(Clone, Default)]
 458: struct TypedSum {
 459:     integer: i64,
 460:     float: Option<f64>,
 461: }
 462: 
 463: impl TypedSum {
 464:     fn add(&mut self, typ: FieldType, sample: &[u8]) {
 465:         if sample.is_empty() {
 466:             return;
 467:         }
 468:         match typ {
 469:             TFloat => {
 470:                 let float: f64 = from_bytes::<f64>(sample).unwrap();
 471:                 match self.float {
 472:                     None => {
 473:                         self.float = Some((self.integer as f64) + float);
 474:                     }
 475:                     Some(ref mut f) => {
 476:                         *f += float;
 477:                     }
 478:                 }
 479:             }
 480:             TInteger => {
 481:                 if let Some(ref mut float) = self.float {
 482:                     *float += from_bytes::<f64>(sample).unwrap();
 483:                 } else {
 484:                     self.integer += from_bytes::<i64>(sample).unwrap();
 485:                 }
 486:             }
 487:             _ => {}
 488:         }
 489:     }
 490: 
 491:     fn show(&self, typ: FieldType) -> Option<String> {
 492:         match typ {
 493:             TNull | TUnicode | TUnknown  => None,
 494:             TInteger => Some(self.integer.to_string()),
 495:             TFloat => Some(self.float.unwrap_or(0.0).to_string()),
 496:         }
 497:     }
 498: }
