 102: type ByteString = Vec<u8>;
 103: type Headers = csv::ByteRecord;
 104: type FTable = Frequencies<Vec<u8>>;
 105: type FTables = Vec<Frequencies<Vec<u8>>>;
 106: 
 107: impl Args {
 108:     fn rconfig(&self) -> Config {
 109:         Config::new(&self.arg_input)
 110:             .delimiter(self.flag_delimiter)
 111:             .no_headers(self.flag_no_headers)
 112:             .select(self.flag_select.clone())
 113:     }
 114: 
 115:     fn counts(&self, ftab: &FTable) -> Vec<(ByteString, u64)> {
 116:         let mut counts = if self.flag_asc {
 117:             ftab.least_frequent()
 118:         } else {
 119:             ftab.most_frequent()
 120:         };
 121:         if self.flag_limit > 0 {
 122:             counts = counts.into_iter().take(self.flag_limit).collect();
 123:         }
 124:         counts.into_iter().map(|(bs, c)| {
 125:             if b"" == &**bs {
 126:                 (b"(NULL)"[..].to_vec(), c)
 127:             } else {
 128:                 (bs.clone(), c)
 129:             }
 130:         }).collect()
 131:     }
 132: 
 133:     fn sequential_ftables(&self) -> CliResult<(Headers, FTables)> {
 134:         let mut rdr = self.rconfig().reader()?;
 135:         let (headers, sel) = self.sel_headers(&mut rdr)?;
 136:         Ok((headers, self.ftables(&sel, rdr.byte_records())?))
 137:     }
 138: 
 139:     fn parallel_ftables(&self, idx: &mut Indexed<fs::File, fs::File>)
 140:                        -> CliResult<(Headers, FTables)> {
 141:         let mut rdr = self.rconfig().reader()?;
 142:         let (headers, sel) = self.sel_headers(&mut rdr)?;
 143: 
 144:         if idx.count() == 0 {
 145:             return Ok((headers, vec![]));
 146:         }
 147: 
 148:         let chunk_size = util::chunk_size(idx.count() as usize, self.njobs());
 149:         let nchunks = util::num_of_chunks(idx.count() as usize, chunk_size);
 150: 
 151:         let pool = ThreadPool::new(self.njobs());
 152:         let (send, recv) = chan::sync(0);
 153:         for i in 0..nchunks {
 154:             let (send, args, sel) = (send.clone(), self.clone(), sel.clone());
 155:             pool.execute(move || {
 156:                 let mut idx = args.rconfig().indexed().unwrap().unwrap();
 157:                 idx.seek((i * chunk_size) as u64).unwrap();
 158:                 let it = idx.byte_records().take(chunk_size);
 159:                 send.send(args.ftables(&sel, it).unwrap());
 160:             });
 161:         }
 162:         drop(send);
 163:         Ok((headers, merge_all(recv.iter()).unwrap()))
 164:     }
 165: 
 166:     fn ftables<I>(&self, sel: &Selection, it: I) -> CliResult<FTables>
 167:             where I: Iterator<Item=csv::Result<csv::ByteRecord>> {
 168:         let null = &b""[..].to_vec();
 169:         let nsel = sel.normal();
 170:         let mut tabs: Vec<_> =
 171:             (0..nsel.len()).map(|_| Frequencies::new()).collect();
 172:         for row in it {
 173:             let row = row?;
 174:             for (i, field) in nsel.select(row.into_iter()).enumerate() {
 175:                 let field = trim(field.to_vec());
 176:                 if !field.is_empty() {
 177:                     tabs[i].add(field);
 178:                 } else {
 179:                     if !self.flag_no_nulls {
 180:                         tabs[i].add(null.clone());
 181:                     }
 182:                 }
 183:             }
 184:         }
 185:         Ok(tabs)
 186:     }
 187: 
 188:     fn sel_headers<R: io::Read>(&self, rdr: &mut csv::Reader<R>)
 189:                   -> CliResult<(csv::ByteRecord, Selection)> {
 190:         let headers = rdr.byte_headers()?;
 191:         let sel = self.rconfig().selection(headers)?;
 192:         Ok((sel.select(headers).map(|h| h.to_vec()).collect(), sel))
 193:     }
 194: 
 195:     fn njobs(&self) -> usize {
 196:         if self.flag_jobs == 0 { util::num_cpus() } else { self.flag_jobs }
 197:     }
 198: }
 199: 
 200: fn trim(bs: ByteString) -> ByteString {
 201:     match String::from_utf8(bs) {
 202:         Ok(s) => s.trim().as_bytes().to_vec(),
 203:         Err(bs) => bs.into_bytes(),
 204:     }
 205: }
