  57:                            column will be 1-based indices instead of header
  58:                            names.
  59:     -d, --delimiter <arg>  The field delimiter for reading CSV data.
  60:                            Must be a single character. (default: ,)
  61: ";
  62: 
  63: #[derive(Clone, Deserialize)]
  64: struct Args {
  65:     arg_input: Option<String>,
  66:     flag_select: SelectColumns,
  67:     flag_limit: usize,
  68:     flag_asc: bool,
  69:     flag_no_nulls: bool,
