 166:     fn ftables<I>(&self, sel: &Selection, it: I) -> CliResult<FTables>
 167:             where I: Iterator<Item=csv::Result<csv::ByteRecord>> {
 168:         let null = &b""[..].to_vec();
 169:         let nsel = sel.normal();
 170:         let mut tabs: Vec<_> =
 171:             (0..nsel.len()).map(|_| Frequencies::new()).collect();
 172:         for row in it {
 173:             let row = row?;
 174:             for (i, field) in nsel.select(row.into_iter()).enumerate() {
 175:                 let field = trim(field.to_vec());
 176:                 if !field.is_empty() {
 177:                     tabs[i].add(field);
 178:                 } else {
 179:                     if !self.flag_no_nulls {
 180:                         tabs[i].add(null.clone());
 181:                     }
 182:                 }
 183:             }
 184:         }
 185:         Ok(tabs)
 186:     }
 187: 
 188:     fn sel_headers<R: io::Read>(&self, rdr: &mut csv::Reader<R>)
 189:                   -> CliResult<(csv::ByteRecord, Selection)> {
 190:         let headers = rdr.byte_headers()?;
 191:         let sel = self.rconfig().selection(headers)?;
 192:         Ok((sel.select(headers).map(|h| h.to_vec()).collect(), sel))
 193:     }
 194: 
 195:     fn njobs(&self) -> usize {
 196:         if self.flag_jobs == 0 { util::num_cpus() } else { self.flag_jobs }
 197:     }
 198: }
 199: 
 200: fn trim(bs: ByteString) -> ByteString {
 201:     match String::from_utf8(bs) {
 202:         Ok(s) => s.trim().as_bytes().to_vec(),
 203:         Err(bs) => bs.into_bytes(),
 204:     }
 205: }
