 166:     fn ftables<I>(&self, sel: &Selection, it: I) -> CliResult<FTables>
 167:             where I: Iterator<Item=csv::Result<csv::ByteRecord>> {
 168:         let null = &b""[..].to_vec();
 169:         let nsel = sel.normal();
 170:         let mut tabs: Vec<_> =
 171:             (0..nsel.len()).map(|_| Frequencies::new()).collect();
