 502:         match (self.float, other.float) {
 503:             (Some(f1), Some(f2)) => self.float = Some(f1 + f2),
 504:             (Some(f1), None) => self.float = Some(f1 + (other.integer as f64)),
 505:             (None, Some(f2)) => self.float = Some((self.integer as f64) + f2),
 506:             (None, None) => self.integer += other.integer,
 507:         }
 508:     }
